37:       board: source.board.map(row => row.map(p => p ? { ...p } : null)),
38:       kings: { ...source.kings },
39:       rooks: { w: { ...source.rooks.w }, b: { ...source.rooks.b } },
40:       captured: { w: source.captured.w.map(p => ({ ...p })), b: source.captured.b.map(p => ({ ...p })) },
41:       ep: source.ep ? { ...source.ep } : null,
