85:   function pseudoMoves(s, r, c) {
86:     const p = s.board[r][c];
87:     if (!p) return [];
88:     const moves = [], add = (rr, cc, extra = {}) => {
89:       if (!inside(rr, cc)) return false;
90:       const target = s.board[rr][cc];
91:       if (target?.color === p.color || target?.type === 'K') return false;
92:       moves.push({ from: { r, c }, to: { r: rr, c: cc }, ...extra });
93:       return !target;
94:     };
95:     if (p.type === 'P') {
96:       const dir = p.color === 'w' ? -1 : 1, start = p.color === 'w' ? 6 : 1;
97:       const one = r + dir;
98:       if (inside(one, c) && !s.board[one][c]) {
99:         add(one, c);
100:         if (r === start && !p.moved && !s.board[r + 2 * dir][c]) add(r + 2 * dir, c, { double: true });
101:       }
102:       for (const dc of [-1, 1]) {
103:         const rr = r + dir, cc = c + dc;
104:         if (!inside(rr, cc)) continue;
105:         if (s.board[rr][cc] && s.board[rr][cc].color !== p.color && s.board[rr][cc].type !== 'K') add(rr, cc);
106:         else if (s.ep && s.ep.r === rr && s.ep.c === cc) moves.push({ from: { r, c }, to: { r: rr, c: cc }, ep: true });
107:       }
108:       return moves;
109:     }
110:     if (p.type === 'N') {
111:       for (const [dr, dc] of [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]]) add(r + dr, c + dc);
112:       return moves;
113:     }
114:     if (p.type === 'K') {
115:       for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) if (dr || dc) add(r + dr, c + dc);
116:       if (!p.moved && p.id === s.kings[p.color] && !inCheck(s, p.color)) {
117:         const home = p.color === 'w' ? 7 : 0;
118:         for (const side of ['k', 'q']) {
