120:           const rook = s.board[home][rookCol];
121:           const emptyCols = side === 'k' ? [5, 6] : [1, 2, 3];
122:           const transitCols = side === 'k' ? [5, 6] : [3, 2];
123:           if (r !== home || c !== 4 || !rook || rook.id !== rookId || rook.type !== 'R' || rook.moved) continue;
124:           if (emptyCols.some(col => s.board[home][col])) continue;
125:           if (transitCols.some(col => attacked(s, home, col, opponent(p.color)))) continue;
126:           moves.push({ from: { r, c }, to: { r: home, c: side === 'k' ? 6 : 2 }, castle: side });
127:         }
128:       }
129:       return moves;
130:     }
131:     const dirs = [];
132:     if (p.type === 'R' || p.type === 'Q') dirs.push([-1,0], [1,0], [0,-1], [0,1]);
133:     if (p.type === 'B' || p.type === 'Q') dirs.push([-1,-1], [-1,1], [1,-1], [1,1]);
134:     for (const [dr, dc] of dirs) {
135:       let rr = r + dr, cc = c + dc;
136:       while (add(rr, cc)) { rr += dr; cc += dc; }
137:     }
138:     return moves;
139:   }
