141:   function applyMove(s, move, promotion = null) {
142:     const { r: fr, c: fc } = move.from, { r: tr, c: tc } = move.to;
143:     const piece = s.board[fr][fc];
144:     let captured = move.ep ? s.board[fr][tc] : s.board[tr][tc];
145:     if (move.ep) s.board[fr][tc] = null;
146:     s.board[fr][fc] = null;
147:     if (captured) {
148:       captured = { ...captured };
149:       s.captured[piece.color].push(captured);
150:       if (piece.type !== 'K') piece.type = captured.type;
151:     }
152:     piece.moved = true;
153:     s.board[tr][tc] = piece;
154:     if (move.castle) {
155:       const rookFrom = move.castle === 'k' ? 7 : 0, rookTo = move.castle === 'k' ? 5 : 3;
156:       const rook = s.board[tr][rookFrom];
157:       s.board[tr][rookFrom] = null;
158:       s.board[tr][rookTo] = rook;
159:       rook.moved = true;
160:     }
161:     if (promotion && piece.type === 'P' && (tr === 0 || tr === 7)) piece.type = promotion;
162:     s.ep = move.double ? { r: (fr + tr) / 2, c: fc, pawn: piece.id } : null;
163:     s.lastMove = { from: { ...move.from }, to: { ...move.to } };
