*{
box-sizing:border-box}
 :root{
color-scheme:dark;--bg:#101619;--panel:#192124;--panel2:#20292c;--line:#303a3d;--muted:#839093;--text:#f2f1e9;--lime:#d8f36a;--lime-dark:#a8c747;--cream:#e9e3d3;--sage:#829088;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}
 html{
min-width:320px;background:var(--bg)}
body{
margin:0;background:radial-gradient(ellipse at 38% 38%,#1b2526 0%,var(--bg) 62%);color:var(--text);font-family:var(--sans);min-height:100vh}
.app-shell{
max-width:1320px;margin:0 auto;padding:0 48px}
.topbar{
height:76px;border-bottom:1px solid #293235;display:flex;align-items:center;justify-content:space-between}
.brand{
display:flex;align-items:center;gap:12px;color:#f4f2e8;text-decoration:none;font:700 15px var(--display);letter-spacing:.09em}
.brand-mark{
display:grid;place-items:center;width:34px;height:34px;border:1px solid #43504b;border-radius:10px;color:var(--lime);font-size:21px}
.brand-light{
font-weight:400;color:#939f9b}
.topbar-right{
display:flex;align-items:center;gap:22px}
.edition,.eyebrow,.section-heading h3,.history-count,.live-label,.side-footnote,.site-footer,.board-footer,.round-pill,.secondary-button,.new-game-button{
font-family:var(--mono);letter-spacing:.09em}
.edition{
font-size:10px;color:#a8b2ad;display:flex;align-items:center;gap:9px}
.edition i,.live-label i,.footer-state i,.round-dot{
width:7px;height:7px;background:var(--lime);border-radius:50%;display:inline-block;box-shadow:0 0 10px #d8f36655}
.icon-button{
width:32px;height:32px;border:1px solid #3b474a;background:#192124;color:#c6ceca;border-radius:50%;font:500 15px var(--mono);cursor:pointer;transition:.18s}
.icon-button:hover{
border-color:var(--lime);color:var(--lime)}
.game-layout{
display:grid;grid-template-columns:minmax(0,790px) minmax(270px,330px);gap:64px;justify-content:center;padding:35px 0 24px}
.board-heading{
display:flex;align-items:flex-end;justify-content:space-between;margin:0 0 22px}
.eyebrow{
font-size:9px;color:#9daaa4;margin:0 0 8px;letter-spacing:.14em}
.board-heading h1{
font:600 clamp(26px,3vw,38px)/1.07 var(--display);letter-spacing:-.05em;margin:0;color:#f2f1e9}
.mobile-break{
display:none}
.round-pill{
border:1px solid #374345;padding:9px 11px 8px;display:flex;align-items:center;gap:9px;color:#c5cfca;font-size:9px;white-space:nowrap;margin-bottom:3px}
.round-dot{
width:6px;height:6px}
.board-frame{
padding:10px 12px 0;border:1px solid #364143;background:#192124;border-radius:7px;box-shadow:0 20px 50px #0003}
.player-strip{
height:45px;display:flex;align-items:center;gap:10px;padding:0 4px;position:relative}
.opponent-strip{
margin-bottom:7px}
.active-strip{
margin-top:7px}
.avatar{
width:29px;height:29px;border-radius:6px;display:grid;place-items:center;font-size:20px;line-height:1}
.black-avatar{
background:#303a3b;color:#e3e9dc}
.white-avatar{
background:var(--lime);color:#18201a}
.player-info{
display:flex;flex-direction:column;gap:2px;min-width:95px}
.player-info strong{
font-size:11px;font-weight:600}
.player-info>span{
font-size:9px;color:#9ba7a2}
.you-label{
font-size:9px;color:#afbf5a!important}
.captured-tray{
margin-left:auto;display:flex;align-items:center;gap:0;max-width:51%;overflow:hidden;height:26px}
.captured-piece{
font-size:15px;margin-left:-3px;opacity:.72;filter:drop-shadow(0 1px 1px #0008)}
.captured-piece:first-child{
margin-left:0}
.captured-piece.light-piece{
color:#f0eddd;text-shadow:0 1px 2px #202020}
.captured-piece.dark-piece{
color:#8f9a8d;text-shadow:0 1px 2px #000}
.check-tag{
font:9px var(--mono);color:#ff8c77;border:1px solid #824e43;padding:4px 6px;border-radius:3px;letter-spacing:.06em;margin-left:auto}
.check-tag.hidden{
display:none}
.board-wrap{
position:relative;padding:0 17px 17px 17px}
.board{
aspect-ratio:1/1;width:100%;display:grid;grid-template:repeat(8,1fr)/repeat(8,1fr);overflow:hidden;border:1px solid #222b28;touch-action:manipulation;user-select:none}
.square{
position:relative;display:grid;place-items:center;cursor:pointer;aspect-ratio:1/1;outline:none}
.square.light{
background:#d9d4c3}
.square.dark{
background:#74847a}
.square.selected{
background:#aabe53}
.square.last-move.light{
background:#c9d58b}
.square.last-move.dark{
background:#94a665}
.square.in-check{
background:#b35f50!important}
.square:focus-visible{
z-index:2;box-shadow:inset 0 0 0 3px #fff}
.piece{
font-family:'DejaVu Sans',serif;font-size:clamp(30px,5.2vw,56px);line-height:1;z-index:2;transform:translateY(-1px);transition:transform .12s,filter .12s;pointer-events:none}
.square:hover .piece{
transform:translateY(-3px)}
.piece.white{
color:#fffdf1;text-shadow:0 2px 2px #28312c,0 0 1px #28312c,1px 1px 0 #727d70}
.piece.black{
color:#26302b;text-shadow:0 1px 1px #e6e1d3,0 0 1px #e6e1d3}
.power-badge{
position:absolute;z-index:3;right:5px;bottom:4px;min-width:15px;height:15px;padding:0 3px;display:grid;place-items:center;border-radius:3px;background:#29342e;color:#eff4df;font:8px var(--mono);box-shadow:0 1px 2px #0003}
.piece.white+.power-badge{
background:#f1eddd;color:#455148}
.legal-dot{
width:26%;height:26%;background:#21312845;border-radius:50%;position:absolute;z-index:1;pointer-events:none}
.legal-capture{
position:absolute;inset:4px;border:3px solid #28372c7a;border-radius:50%;z-index:1;pointer-events:none}
.square:hover .legal-dot{
background:#21312870}
.coordinate{
position:absolute;font:9px var(--mono);color:#b4bdaf;line-height:1}
.files-top,.files-bottom{
left:17px;right:17px;height:13px;display:grid;grid-template-columns:repeat(8,1fr);align-items:center;text-align:center}
.files-top{
top:1px}
.files-bottom{
bottom:1px}
.ranks-left,.ranks-right{
top:17px;bottom:17px;width:13px;display:grid;grid-template-rows:repeat(8,1fr);align-items:center;text-align:center}
.ranks-left{
left:0}
.ranks-right{
right:0}
.coordinate.dark-coordinate{
color:#728076}
.board-footer{
display:flex;justify-content:space-between;align-items:center;padding:11px 2px 0;font-size:8px;color:#7f8d88}
.board-footer kbd{
font:inherit;color:#c3ccc2;border:1px solid #3c4748;border-radius:2px;padding:3px 4px}
.footer-state{
display:flex;align-items:center;gap:7px}
.footer-state i{
width:5px;height:5px}
.side-panel{
padding-top:47px;min-width:0}
.turn-card{
border:1px solid #424e3a;background:linear-gradient(140deg,#29332b,#202927 82%);border-radius:6px;padding:18px 17px 15px;position:relative;overflow:hidden}
.turn-card:after{
content:'';position:absolute;width:135px;height:135px;border:1px solid #d8f36612;right:-84px;top:-83px;border-radius:50%;box-shadow:0 0 0 18px #d8f36608,0 0 0 38px #d8f36605}
.turn-top{
display:flex;align-items:center;justify-content:space-between}
.turn-top .eyebrow{
margin:0;color:#c5d86b}
.turn-indicator{
color:var(--lime);font-size:14px}
.turn-main{
display:flex;align-items:center;gap:12px;margin:17px 0 16px}
.turn-king{
font:39px 'DejaVu Sans',serif;width:46px;height:46px;display:grid;place-items:center;color:#fffdf1;background:#38443a;border-radius:5px;text-shadow:0 2px 2px #222}
.turn-king.black-turn{
color:#26302b;text-shadow:0 1px 1px #f0eddd;background:#a0ab9e}
.turn-main h2{
font:600 19px var(--display);letter-spacing:-.04em;margin:0 0 3px}
.turn-main p{
font-size:10px;color:#aab4ae;margin:0}
.turn-divider{
height:1px;background:#465047;margin:0 -1px 13px}
.swap-note{
display:flex;align-items:center;gap:10px}
.swap-icon{
font:21px var(--display);color:var(--lime);width:29px;height:29px;display:grid;place-items:center;background:#d8f36616;border-radius:4px}
.swap-note span:last-child{
display:flex;flex-direction:column;gap:3px}
.swap-note strong{
font-size:10px;font-weight:600}
.swap-note small{
font-size:9px;color:#aab4ae}
.panel-block{
margin-top:25px}
.section-heading{
display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
.section-heading h3{
margin:0;color:#aab5af;font-size:9px;font-weight:500;letter-spacing:.13em}
.live-label{
display:flex;align-items:center;gap:6px;font-size:8px;color:#9aa69c}
.live-label i{
width:5px;height:5px}
.power-list{
border-top:1px solid #303a3d;border-bottom:1px solid #303a3d;display:grid;grid-template-columns:repeat(3,1fr);padding:10px 0 9px;gap:9px 4px}
.power-item{
display:flex;align-items:center;gap:6px;min-width:0}
.power-glyph{
font:18px 'DejaVu Sans',serif;color:#e8e7d9;line-height:1;width:20px;text-align:center}
.power-name{
display:flex;flex-direction:column;gap:1px;min-width:0}
.power-name strong{
font-size:9px;font-weight:600;color:#e7e9dd}
.power-name small{
font:8px var(--mono);color:#84918a}
.power-item.is-zero{
opacity:.36}
.move-block{
margin-top:23px}
.history-count{
color:#7d8c86;font-size:8px}
.history-list{
border-top:1px solid #303a3d;height:117px;overflow:auto;scrollbar-width:thin;scrollbar-color:#48524e transparent}
.empty-history{
height:100%;display:flex;align-items:center;justify-content:center;gap:11px;color:#76837e}
.empty-history>span{
font-size:23px;color:#98aa53}
.empty-history p{
font-size:10px;line-height:1.55;margin:0}
.history-row{
display:grid;grid-template-columns:30px 1fr 1fr;min-height:27px;align-items:center;border-bottom:1px solid #293335;font:10px var(--mono)}
.history-row:nth-child(odd){
background:#ffffff04}
.history-index{
color:#77847e;padding-left:7px}
.history-move{
color:#d9dfd2;padding:0 3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.history-move:last-child{
color:#aab6ab}
.action-row{
display:flex;gap:8px;margin-top:18px}
.secondary-button{
background:#1b2426;border:1px solid #384345;border-radius:4px;color:#bec8c1;flex:1;height:34px;font-size:8px;cursor:pointer;transition:.15s}
.secondary-button span{
font-size:15px;vertical-align:-1px;margin-right:4px;color:#d9f36b}
.secondary-button:hover:not(:disabled){
border-color:#9bb34e;color:#f3f5e8}
.secondary-button:disabled{
opacity:.4;cursor:not-allowed}
.new-game-button{
width:100%;height:39px;margin-top:9px;border:0;border-radius:4px;background:var(--lime);color:#20271c;font-size:9px;font-weight:500;cursor:pointer;transition:.15s}
.new-game-button:hover{
background:#e5ff83;transform:translateY(-1px)}
.new-game-button span{
font-size:15px;vertical-align:-1px;margin-right:5px}
.side-footnote{
font-size:8px;text-align:center;color:#68756f;margin:18px 0 0}
.side-footnote span{
font-size:11px;color:#bbce5e;margin-left:4px}
.site-footer{
height:44px;border-top:1px solid #293235;display:flex;justify-content:space-between;align-items:center;color:#a2aea6;font-size:8px}
.site-footer .muted{
color:#68756f}
.spark{
color:var(--lime);font-size:13px;margin-left:4px}
.modal-backdrop,.promotion-backdrop{
position:fixed;inset:0;background:#080d0dcc;backdrop-filter:blur(6px);display:grid;place-items:center;z-index:10;padding:18px}
.hidden{
display:none!important}
.modal{
position:relative;width:min(440px,100%);background:#1b2425;border:1px solid #414c43;border-radius:8px;padding:29px 30px 25px;box-shadow:0 30px 80px #0009}
.modal-close{
position:absolute;right:15px;top:15px;font-size:20px}
.modal-symbol{
width:42px;height:42px;display:grid;place-items:center;background:#d8f36618;color:var(--lime);font-size:23px;border-radius:5px;margin-bottom:22px}
.modal h2,.promotion-modal h2{
font:600 25px var(--display);letter-spacing:-.04em;margin:0 0 12px}
.rule-copy{
font-size:12px;line-height:1.7;color:#bdc6bf}
.rule-copy p{
margin:0 0 10px}
.rule-copy ul{
padding-left:17px;margin:9px 0 13px}
.rule-copy li{
margin:6px 0}
.rule-copy b{
color:#eff1e4}
.modal-action{
margin-top:7px}
.promotion-modal{
width:min(360px,100%);background:#1b2425;border:1px solid #414c43;border-radius:8px;padding:27px;box-shadow:0 30px 80px #0009}
.promotion-modal h2{
font-size:20px}
.promotion-options{
display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:18px}
.promotion-choice{
background:#2a3432;border:1px solid #46524a;border-radius:5px;color:#eef0df;cursor:pointer;padding:9px 4px 8px;display:flex;flex-direction:column;align-items:center;gap:5px}
.promotion-choice:hover{
border-color:var(--lime);background:#364034}
.promotion-choice .piece{
font-size:34px}
.promotion-choice small{
font:8px var(--mono);color:#aab6ad}
.toast{
position:fixed;bottom:23px;left:50%;transform:translate(-50%,12px);background:#e4edc1;color:#242b1f;padding:10px 16px;border-radius:4px;font:10px var(--mono);letter-spacing:.04em;opacity:0;pointer-events:none;transition:.22s;z-index:20;white-space:nowrap}
.toast.show{
opacity:1;transform:translate(-50%,0)}

@media (min-width:1100px){
.board{
max-height:690px}
.piece{
font-size:clamp(32px,4.35vw,57px)}
}

@media (max-width:1050px){
.app-shell{
padding:0 28px}
.game-layout{
grid-template-columns:minmax(0,1fr) 280px;gap:32px}
.side-panel{
padding-top:43px}
.board-wrap{
padding-left:15px;padding-right:15px}
.files-top,.files-bottom{
left:15px;right:15px}
.piece{
font-size:clamp(30px,5.5vw,53px)}
}

@media (max-width:760px){
.app-shell{
padding:0 17px}
.topbar{
height:62px}
.edition{
font-size:8px}
.topbar-right{
gap:12px}
.game-layout{
display:flex;flex-direction:column;gap:0;padding:24px 0 17px}
.board-heading{
margin-bottom:15px}
.board-heading h1{
font-size:29px}
.mobile-break{
display:none}
.round-pill{
font-size:8px;padding:8px}
.board-frame{
padding:8px 8px 0}
.player-strip{
height:39px}
.opponent-strip{
margin-bottom:4px}
.active-strip{
margin-top:4px}
.board-wrap{
padding:0 14px 14px}
.files-top,.files-bottom{
left:14px;right:14px;height:11px}
.ranks-left,.ranks-right{
top:14px;bottom:14px;width:11px}
.coordinate{
font-size:8px}
.piece{
font-size:clamp(28px,9vw,50px)}
.power-badge{
font-size:7px;right:3px;bottom:2px;min-width:13px;height:13px}
.side-panel{
padding-top:22px;display:grid;grid-template-columns:1fr 1fr;gap:0 18px}
.turn-card{
grid-column:1/-1}
.panel-block{
margin-top:20px}
.power-block{
grid-column:1}
.move-block{
grid-column:2}
.power-list{
grid-template-columns:repeat(2,1fr);gap:10px 4px}
.history-list{
height:119px}
.action-row,.new-game-button,.side-footnote{
grid-column:1/-1}
.action-row{
margin-top:16px}
.site-footer{
font-size:7px}
.board-footer{
font-size:7px}
.footer-state{
font-size:7px}
}

@media (max-width:460px){
.app-shell{
padding:0 12px}
.brand{
font-size:13px;gap:8px}
.brand-mark{
width:30px;height:30px}
.edition{
max-width:114px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.04em}
.board-heading h1{
font-size:25px}
.mobile-break{
display:block}
.round-pill{
font-size:7px;padding:7px 8px}
.board-wrap{
padding-left:12px;padding-right:12px}
.files-top,.files-bottom{
left:12px;right:12px}
.ranks-left,.ranks-right{
top:12px;bottom:12px}
.piece{
font-size:clamp(27px,10.5vw,44px)}
.side-panel{
gap:0 12px}
.power-item{
gap:3px}
.power-glyph{
font-size:16px;width:17px}
.power-name strong{
font-size:8px}
.power-name small{
font-size:7px}
.section-heading h3{
font-size:8px}
.site-footer span:last-child{
display:none}
.captured-tray{
max-width:48%}
.captured-piece{
font-size:13px}
.player-info{
min-width:74px}
}

@media (prefers-reduced-motion:reduce){
*,*::before,*::after{
scroll-behavior:auto!important;transition:none!important}
}

