.board-wrap{position:relative;padding:0 17px 17px 17px}
.board{aspect-ratio:1/1;width:100%;display:grid;grid-template:repeat(8,1fr)/repeat(8,1fr);overflow:hidden;border:1px solid #222b28;touch-action:manipulation;user-select:none}
.square{position:relative;display:grid;place-items:center;cursor:pointer;aspect-ratio:1/1;outline:none}
@media (min-width:1100px){.board{max-height:690px}
.board{width:min(100%,calc(100svh - 420px));max-height:none;margin-inline:auto}
.board-wrap{padding-left:15px;padding-right:15px}
.board-wrap{padding:0 14px 14px}
.board-wrap{padding-left:12px;padding-right:12px}
